initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT contains a Context Source Registration 
        with id equal to ${context_source_registration_id}
        and payload set to ${context_source_registration_payload_file_path}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Context Source Registration With Return with Response Status Code set to 405     and
        Delete Context Source Registration With Return with Response Body containing the type '${EMPTY}'     and
        Delete Context Source Registration With Return with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'DELETE'
        Delete Context Source Registration with id set to '${EMPTY}'
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Context Source Registration With Return with Response Status Code set to 400     and
        Delete Context Source Registration With Return with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData'     and
        Delete Context Source Registration With Return with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'DELETE'
        Delete Context Source Registration with id set to 'invalidURI'
}
